const std::vector<Node*>& neighbors = graph.get_neighbors(current_node);

for (Node* neighbor : neighbors) {
    if (neighbor->visited) {
        continue;
    }

    // Calculate g value (cost from start to this neighbor)
    double tentative_g = current_node->g + graph.get_cost(current_node, neighbor);

    // Check if this path is better than any previous path to this neighbor
    if (tentative_g < neighbor->g) {
        neighbor->parent = current_node;
        neighbor->g = tentative_g;
        neighbor->h = calculate_heuristic(neighbor, end_node);
        neighbor->f = neighbor->g + neighbor->h;

        // Check if neighbor is already in open list
        bool in_open_list = false;
        for (Node* node : open_list) {
            if (node == neighbor) {
                in_open_list = true;
                break;
            }
        }

        if (!in_open_list) {
            open_list.push_back(neighbor);
        }
    }
}

